<template><section class="grid"><div class="card"><h1>AI 소비 분석</h1><form class="form" @submit.prevent="createMonthly"><input v-model.number="year" type="number"><input v-model.number="month" type="number" min="1" max="12"><button>월별 분석 생성</button></form><div v-if="monthly"><h3>{{monthly.year}}년 {{monthly.month}}월</h3><p>총 소비 {{Number(monthly.total_amount).toLocaleString()}}원</p><pre>{{monthly.category_summary}}</pre><button @click="createAI">AI 분석 요청</button></div></div><div class="card"><h2>분석 결과</h2><div v-for="a in aiResults" :key="a.id"><span class="badge">{{a.status}}</span><pre>{{a.feedback}}</pre></div></div></section></template>
<script setup>import { onMounted, ref } from 'vue'; import api from '@/api/axios'; const now=new Date(); const year=ref(now.getFullYear()); const month=ref(now.getMonth()+1); const monthly=ref(null); const aiResults=ref([]); const loadAI=async()=>{aiResults.value=(await api.get('/api/v1/analysis/ai/')).data}; const createMonthly=async()=>{monthly.value=(await api.post('/api/v1/analysis/monthly/create/',{year:year.value,month:month.value})).data}; const createAI=async()=>{await api.post('/api/v1/analysis/ai/create/',{analysis_id:monthly.value.id}); await loadAI()}; onMounted(loadAI)</script>
